    25	/// THE GATEKEEPER: Tonic gRPC Interceptor on port 18789.
    26	///
    27	/// Enforces the Absolute Base rule: if the `x-ghostbridge-footprint` provided by Xray
    28	/// does not perfectly match the hashed footprint sitting in shared memory, the payload
    29	/// is rejected. Once validated, embeds the `x-ghostbridge-trace-id` into Tonic Request
    30	/// extensions so the Chatbot and Qdrant semantic search on the Accountability Page
    31	/// have the exact Trace ID needed to link the session.
    32	#[derive(Clone, Debug)]
    33	pub struct GhostbridgeInterceptor;
    34	
    35	impl tonic::service::Interceptor for GhostbridgeInterceptor {
    36	    fn call(&mut self, req: Request<()>) -> Result<Request<()>, Status> {
    37	        ghostbridge_interceptor(req)
    38	    }
    39	}
