    34	/// Lightweight shape check used to test whether a value satisfies one branch
    35	/// of a `FieldType::OneOf` discriminated union.
    36	fn value_matches_field_type(field_type: &FieldType, value: &Value) -> bool {
    37	    match (field_type, value) {
    38	        (FieldType::String, Value::String(_)) => true,
    39	        (FieldType::Integer, Value::Static(StaticNode::I64(_) | StaticNode::U64(_))) => true,
    40	        (FieldType::Float, Value::Static(StaticNode::F64(_))) => true,
    41	        (FieldType::Boolean, Value::Static(StaticNode::Bool(_))) => true,
    42	        (FieldType::Object(_), Value::Object(_)) => true,
    43	        (FieldType::Array(_), Value::Array(_)) => true,
    44	        (FieldType::Enum(values), Value::String(s)) => values.contains(&s.to_string()),
    45	        (FieldType::OneOf(branches), v) => branches
    46	            .iter()
    47	            .any(|branch| value_matches_field_type(branch, v)),
    48	        (FieldType::Any, _) => true,
    49	        _ => false,
    50	    }
    51	}
