    66	/// Atomically publish `bytes` to a `/dev/shm` path via a sibling temp file +
    67	/// rename, so readers see either the old or new content, never a torn write.
    68	fn atomic_write_shm(path: &str, bytes: &[u8]) -> Result<()> {
    69	    let tmp = format!("{}.tmp", path);
    70	    {
    71	        let mut file = std::fs::File::create(&tmp)
    72	            .map_err(|e| anyhow::anyhow!("Cannot create {}: {}", tmp, e))?;
    73	        file.write_all(bytes)
    74	            .map_err(|e| anyhow::anyhow!("Failed to write {}: {}", tmp, e))?;
    75	        file.sync_all()
    76	            .map_err(|e| anyhow::anyhow!("Failed to sync {}: {}", tmp, e))?;
    77	    }
    78	    std::fs::rename(&tmp, path)
    79	        .map_err(|e| anyhow::anyhow!("Failed to rename {} -> {}: {}", tmp, path, e))?;
    80	    Ok(())
    81	}
